 function mushroom(x,z,s=1,color='#ba816b',bouncy=false){const g=group(x,z);cyl(.16*s,.25*s,.9*s,'#e6d9b6',0,.45*s,0,g);const cap=ball(.85*s,color,0,.95*s,0,g,2);cap.scale.set(1,.43,1);for(let i=0;i<6;i++){const a=i*2.4;const dot=ball(.11*s,'#f0dfba',Math.cos(a)*.52*s,1.18*s,Math.sin(a)*.52*s,g,0);dot.scale.y=.3;}if(bouncy)mushrooms.push({x,z,y:g.position.y+1.24*s,r:.83*s,g});else if(s>.5)colliders.push({x,z,r:.6*s});batchStatic(g);}
