 sign(-42,0,'SPACE = A LITTLE EXTRA HOP',.2);bench(-53,-10,.5);
 // Willow Falls: water moves independently of the scenery.
 const fy=ground(26,-46),pool=mesh(new THREE.CircleGeometry(5.6,48),'#85b5af',scene,{roughness:.22,transparent:true,opacity:.85});pool.rotation.x=-Math.PI/2;pool.position.set(24,ground(24,-40)+.14,-40);
 const fallRock=stone(27,-46,3);fallRock.position.y=fy+2;fallRock.scale.set(1.1,1.4,.7);
