 for(let i=0;i<14;i++){const g=new THREE.Group();for(const s of [-1,1]){const wing=ball(.17,i%2?'#e8ca8a':'#d0a4a0',s*.12,0,0,g,0);wing.scale.set(1,.17,1.3);}scene.add(g);butterflies.push({g,x:20+(random()-.5)*23,z:-38+(random()-.5)*25,phase:random()*6});}
 // Cloudrest has a longer switchback route, a steep final scramble, flags, and a summit stamp.
 for(let i=0;i<45;i++){const x=-7+(random()-.5)*47,z=-63+(random()-.5)*46;if(ground(x,z)<4||Math.hypot(x+8,z+68)<8||Math.abs(x+18)<3)continue;if(ground(x,z)>19)stone(x,z,.7+random()*1.5);else tree(x,z,.6+random()*.5,0);}
 const trailFlags=[[-6,-29],[-7,-40],[-14,-48],[-21,-57],[-19,-65],[-15,-72],[-8,-68]];
 for(const [x,z]of trailFlags){const y=ground(x,z);cyl(.045,.065,2.8,'#98947a',x,y+1.4,z);const flag=box(.9,.48,.03,'#c98a6c',x+.42,y+2.5,z);windmills.push({flag,phase:random()*6});}
 const summit=group(-8,-68);for(let i=0;i<6;i++){const a=i/6*Math.PI*2;ball(.35,'#b3b29c',Math.cos(a)*1.5,.12,Math.sin(a)*1.5,summit);}cyl(.14,.18,3.8,'#8a8b71',0,1.9,0,summit);box(1.3,.8,.05,'#d4a473',.6,3.3,0,summit);sign(-11,-69,'CLOUDREST · 128 m',.5);bench(-5,-65,2.4);batchStatic(summit);
 // Shells are exploration keepsakes, not currency. Every one persists.
