 treasurePoints.forEach(([x,z],i)=>{const g=group(x,z);const shell=ball(.32,'#e5cda4',0,.6,0,g,1);shell.scale.set(1,.7,.55);for(let j=-2;j<=2;j++){const line=box(.025,.38,.03,'#c6aa87',j*.08,.63,.17,g);line.rotation.z=-j*.16;}const ring=mesh(new THREE.TorusGeometry(.56,.025,4,24),'#dfcf96',g,{emissive:'#c8bd83',emissiveIntensity:.3});ring.rotation.x=Math.PI/2;ring.position.y=.2;treasures.push({id:'shell-'+i,g,y:g.position.y,phase:random()*6});});
