 for(const [x,z]of [[12,5],[13,5.5],[8,23]]){const g=group(x,z);box(.8,.7,.8,'#ac916d',0,.35,0,g);for(const s of [-1,1])box(.08,.7,.83,'#d3bc91',s*.32,.35,0,g);batchStatic(g);}
 for(let i=0;i<3;i++){const rope=mesh(new THREE.TorusGeometry(.45-i*.08,.035,5,20),'#c3b18b');rope.rotation.x=-Math.PI/2;rope.position.set(9,1.45+i*.04,28);}
 // UI is appended once so old saves and the original fishing screen remain compatible.
