 const ui=document.createElement('div');ui.innerHTML=`<div id="expedition-hud" class="expedition-hud hidden"><span class="eyebrow">A LITTLE FARTHER</span><div><span>✧ <b id="shell-count">0</b> / 12</span><span>♡ <b id="friend-count">0</b> / 7</span></div></div><div id="trail-guide" class="trail-guide hidden"><span id="trail-arrow">↑</span><span><small>TAKE THE SCENIC ROUTE</small><b id="trail-name"></b><em id="trail-distance"></em></span><button id="clear-trail" aria-label="Clear route">×</button></div><div id="climb-hud" class="climb-hud hidden"><span id="climb-label">A LITTLE BREATHER</span><div><i id="climb-energy"></i></div><small>Hold Space on steep ground · rest to recover</small></div><div id="world-map" class="modal-backdrop hidden"><section class="modal map-modal" role="dialog" aria-modal="true" aria-labelledby="map-title"><button class="close" id="close-map" aria-label="Close island map">×</button><span class="eyebrow">THERE'S A LITTLE MORE OUT THERE</span><h2 id="map-title">The farther shores.</h2><p>Pick a trail. Discovered places become little shortcuts home.</p><div class="map-layout"><div class="island-map-art"><svg viewBox="0 0 340 340" role="img" aria-label="Island map: Cloudrest Peak north, Willow Falls northeast, Clover Farm east, Mushroom Woods west, Little Tides south"><rect width="340" height="340" rx="16" fill="#bcd0c4"/><path d="M145 250Q50 230 35 174Q25 120 81 115L126 141Q123 112 119 77Q110 20 172 24Q215 22 213 78Q265 65 282 115L254 159Q318 143 325 211Q327 275 257 264L210 243Q198 307 147 289Z" fill="#d8d3ac"/><path d="M149 242Q60 218 52 173Q43 131 82 131L144 162L135 81Q133 41 173 40Q206 38 198 89L185 111Q242 81 266 116L228 176Q303 162 306 213Q307 254 259 246L207 220Q195 285 156 274Z" fill="#a9bd8f"/><path d="M169 235L172 179L166 133L157 98L169 63M172 179L242 212M172 179L80 171M166 133L243 128" stroke="#f0e3b9" stroke-width="5" stroke-dasharray="4 3" fill="none" stroke-linecap="round"/><path d="M155 80L174 42L195 80Z" fill="#98aa8c"/><path d="M168 56L174 42L182 57Z" fill="#e9e4d2"/><path d="M239 119Q218 132 239 148Q255 134 239 119" fill="#91b9b3"/><text x="169" y="322" text-anchor="middle" fill="#5c7b6b" font-size="8" font-family="Arial" letter-spacing="2">LITTLE TIDES ARCHIPELAGO</text><g id="map-pins"></g><circle id="map-player" r="5" fill="#fff8e0" stroke="#48745e" stroke-width="2"/></svg><span class="map-compass">N ↑</span></div><div id="region-list" class="region-list"></div></div><div class="map-footer" id="map-footer"></div></section></div><div id="animal-dialog" class="modal-backdrop hidden"><section class="modal animal-modal" role="dialog" aria-modal="true" aria-labelledby="animal-name"><button class="close" id="close-animal" aria-label="Close animal visit">×</button><div class="animal-symbol">♡</div><span class="eyebrow" id="animal-kind">A NEW LITTLE FRIEND</span><h2 id="animal-name"></h2><p id="animal-description"></p><div id="animal-actions"><button class="primary" id="pet-animal">A gentle little pet <span>♡</span></button><button class="secondary" id="feed-animal">Share a carrot <span>🥕</span></button><button class="secondary" id="follow-animal">Come wander with me <span>↗</span></button></div><small id="carrot-count"></small></section></div>`;document.body.append(ui);
